    private final java.util.Set<Integer> asyncSteps = new java.util.HashSet<>();

    /**
     * 排下一步（每步之间留 {@link #STEP_MS} 让脉冲跑）。
     *
     * <p>异步步（{@link #REAL_ENTRY} / {@link #BIG_LOAD}）<b>不</b>自动续跑：它们做完自己的等待后
